update public.lessons l set enhancements = $ench${"industryStory":"A candidate who kept blanking on the seven principles under pressure built one daft sentence about elephants. In the real exam a principles question came up, she recalled the sentence in two seconds, and got a mark she'd have lost every previous mock. She still remembers it years later — that's how well a personal mnemonic sticks.","visualAid":{"type":"comparison","title":"Memorise vs understand","headers":["K-level","Type of question","Best approach"],"rows":[["K1","Remember lists & definitions","Mnemonics + flashcards"],["K2","Understand & explain","Analogies + examples"],["K3","Apply a technique","Practise problems (EP, BVA, decision tables)"]]},"davidTip":"Don't waste a mnemonic on something you should understand. If you truly grasp why boundary defects cluster at edges, you never need to memorise BVA — you can derive it. Save the memory tricks for the pure-recall lists.","miniChallenge":"Build a first-letter mnemonic for the seven fundamental test activities (Planning, Monitoring & control, Analysis, Design, Implementation, Execution, Completion). Test it from memory tomorrow.","modelAnswer":"## Example\n\"Please Make A Delicious Ice-cream Every Christmas\" → Planning, Monitoring & control, Analysis, Design, Implementation, Execution, Completion. Silly, ordered, and it sticks after one rehearsal.","badGood":{"label":"using a mnemonic","bad":"You memorise a slick acronym for boundary value analysis and still can't answer a BVA calculation, because it needed applying, not reciting.","good":"You reserve mnemonics for the seven principles and test process, and drill actual EP/BVA problems for the apply questions."},"resourcePreview":{"name":"CTFL Mnemonics Pack","purpose":"Memory hooks for every list examiners love to test, with blanks to build your own.","whenToUse":"Use it for the pure-recall chapters in your final fortnight.","formats":["PDF"]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'istqb-foundation-masterclass'
